const nowIso = new Date().toISOString();

function fail(reason, details) {
    msg.payload = {
        error: reason,
        details: details || {},
        topic: msg.topic,
        receivedAt: nowIso,
        originalPayload: msg.payload
    };
    msg.error = { message: reason, source: 'parse-normalize-mqtt' };
    node.status({ fill: 'red', shape: 'ring', text: reason });
    return [null, msg];
}

function toInt(value) {
    const n = Number(value);
    return Number.isInteger(n) ? n : null;
}

function parseTopic(topic) {
    const parts = String(topic || '').split('/');
    if (parts[0] !== 'f1' || parts[1] !== 'simulation') {
        throw new Error('unsupported topic root');
    }

    const raceId = toInt(parts[2]);
    if (!raceId) throw new Error('invalid raceId in topic');

    if (parts[3] === 'teams') {
        if (parts.length !== 8 || parts[5] !== 'cars') {
            throw new Error('invalid car topic shape');
        }
        const kindMap = { telemetry: 'telemetry', state: 'state', events: 'event' };
        const kind = kindMap[parts[7]];
        const carId = toInt(parts[6]);
        if (!kind) throw new Error('unsupported car topic kind');
        if (!parts[4]) throw new Error('missing teamId in topic');
        if (!carId) throw new Error('invalid carId in topic');
        return { kind, raceId, teamId: parts[4], carId, route: 'car' };
    }

    if (parts[3] === 'race-control') {
        if (parts.length !== 5) throw new Error('invalid race-control topic shape');
        const kindMap = { flags: 'flag', classification: 'classification' };
        const kind = kindMap[parts[4]];
        if (!kind) throw new Error('unsupported race-control topic kind');
        return { kind, raceId, route: 'race-control' };
    }

    throw new Error('unsupported topic branch');
}

function parseTopicCached(topic) {
    const key = String(topic || '');
    let cache = context.get('topicMetaCache') || {};
    if (cache[key]) return cache[key];

    const meta = parseTopic(key);
    if (Object.keys(cache).length >= 64) cache = {};
    cache[key] = meta;
    context.set('topicMetaCache', cache);
    return meta;
}

function parsePayload(payload) {
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer(payload)) payload = payload.toString('utf8');
    if (typeof payload === 'string') {
        const trimmed = payload.trim();
        if (!trimmed) throw new Error('empty payload');
        return JSON.parse(trimmed);
    }
    if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
        return payload;
    }
    throw new Error('payload is not a JSON object');
}

function sameString(left, right) {
    return String(left) === String(right);
}

function sameNumber(left, right) {
    return Number(left) === Number(right);
}

try {
    const meta = parseTopicCached(msg.topic);
    const input = parsePayload(msg.payload);
    const conflicts = [];

    if (input.raceId != null && !sameNumber(input.raceId, meta.raceId)) {
        conflicts.push('raceId');
    }
    if (meta.teamId != null && input.teamId != null && !sameString(input.teamId, meta.teamId)) {
        conflicts.push('teamId');
    }
    if (meta.carId != null && input.carId != null && !sameNumber(input.carId, meta.carId)) {
        conflicts.push('carId');
    }
    if (conflicts.length > 0) {
        return fail('topic/payload mismatch', { conflicts, topicMeta: meta });
    }

    const timestampCandidate = input.timestamp || nowIso;
    const parsedTimestamp = new Date(timestampCandidate);
    if (Number.isNaN(parsedTimestamp.getTime())) {
        return fail('invalid timestamp', { timestamp: timestampCandidate });
    }

    const normalizedPayload = {
        ...input,
        timestamp: parsedTimestamp.toISOString(),
        raceId: meta.raceId
    };
    if (meta.teamId != null) normalizedPayload.teamId = meta.teamId;
    if (meta.carId != null) normalizedPayload.carId = meta.carId;

    const envelope = {
        kind: meta.kind,
        raceId: meta.raceId,
        teamId: meta.teamId || null,
        carId: meta.carId || null,
        topic: msg.topic,
        timestamp: normalizedPayload.timestamp,
        receivedAt: nowIso,
        payload: normalizedPayload
    };

    msg.kind = meta.kind;
    msg.meta = { ...meta, topic: msg.topic, receivedAt: nowIso };
    msg.payload = envelope;
    msg.doc = envelope;
    const lastStatusAt = context.get('lastStatusAt') || 0;
    const nowMs = Date.now();
    if (nowMs - lastStatusAt >= 1000) {
        context.set('lastStatusAt', nowMs);
        node.status({ fill: 'green', shape: 'dot', text: `${meta.kind} race ${meta.raceId}` });
    }
    return [msg, null];
} catch (err) {
    return fail(err.message || 'normalize failed');
}

const TRACK_LENGTH_M = 5793;
const FALLBACK_SPEED_KMH = 200;
const VALID_STATES = {
    INIT: true,
    RUNNING: true,
    PIT: true,
    FAULT: true,
    RETIRED: true,
    FINISHED: true
};

function progress(car) {
    return car.lap + car.trackPos;
}

function validCar(car) {
    return car
        && Number.isInteger(car.raceId)
        && Number.isInteger(car.carId)
        && car.teamId
        && Number.isInteger(car.lap)
        && Number.isFinite(car.trackPos)
        && car.trackPos >= 0
        && car.trackPos <= 1
        && VALID_STATES[car.state || 'RUNNING'];
}

function gapSeconds(leader, car) {
    if (leader.carId === car.carId) return 0;
    const leaderSpeed = Number.isFinite(leader.avgSpeedKmh) && leader.avgSpeedKmh > 1
        ? leader.avgSpeedKmh
        : (Number.isFinite(leader.speed) && leader.speed > 1 ? leader.speed : FALLBACK_SPEED_KMH);
    const gapProgress = Math.max(0, progress(leader) - progress(car));
    const speedMs = Math.max(1, leaderSpeed / 3.6);
    return (gapProgress * TRACK_LENGTH_M) / speedMs;
}

const raceIds = flow.get('raceIds') || [];
let published = 0;
const nowIso = new Date().toISOString();

for (const raceId of raceIds) {
    const carsById = flow.get('race.' + raceId + '.cars') || {};
    const entries = Object.values(carsById)
        .filter(validCar)
        .sort((a, b) => {
            const progressDiff = progress(b) - progress(a);
            if (progressDiff !== 0) return progressDiff;
            return a.carId - b.carId;
        });

    if (entries.length === 0) continue;

    const leader = entries[0];
    const standings = entries.map((car, index) => ({
        position: index + 1,
        carId: car.carId,
        teamId: car.teamId,
        lap: car.lap,
        gap: Number(gapSeconds(leader, car).toFixed(3)),
        state: car.state || 'RUNNING'
    }));

    const snapshot = {
        timestamp: nowIso,
        raceId,
        lap: leader.lap,
        leaderLap: leader.lap,
        standings
    };

    flow.set('race.' + raceId + '.lastClassification', snapshot);
    node.send({
        topic: 'f1/simulation/' + raceId + '/race-control/classification',
        qos: 1,
        retain: true,
        payload: snapshot
    });
    published += 1;
}

if (published === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'waiting telemetry' });
} else {
    node.status({ fill: 'green', shape: 'dot', text: 'published ' + published + ' classification(s)' });
}
return null;

function asInteger(value) {
    const n = Number(value);
    return Number.isInteger(n) ? n : null;
}

function asFiniteNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

const envelope = msg.payload || {};
const sample = envelope.payload || {};
const raceId = asInteger(sample.raceId != null ? sample.raceId : envelope.raceId);
const carId = asInteger(sample.carId != null ? sample.carId : envelope.carId);
const lap = asInteger(sample.lap);
const trackPos = asFiniteNumber(sample.trackPos);
const teamId = sample.teamId != null ? String(sample.teamId) : null;

if (!raceId || !carId || !teamId || lap == null || trackPos == null || trackPos < 0 || trackPos > 1) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'telemetry skipped' });
    return msg;
}

const nowMs = Date.now();
const raceKey = 'race.' + raceId;
const carsKey = raceKey + '.cars';
const cars = flow.get(carsKey) || {};
const previous = cars[String(carId)] || {};
const speed = asFiniteNumber(sample.speed);
const avgSpeedKmh = speed == null
    ? previous.avgSpeedKmh
    : (Number.isFinite(previous.avgSpeedKmh) ? previous.avgSpeedKmh * 0.7 + speed * 0.3 : speed);
const rpm = asInteger(sample.rpm);
const gear = asInteger(sample.gear);
const throttle = asFiniteNumber(sample.throttle);
const brake = asFiniteNumber(sample.brake);
const fuel = asFiniteNumber(sample.fuel);
const drs = typeof sample.drs === 'boolean' ? sample.drs : previous.drs;

function readTireTemp(corner) {
    const next = sample.tireTemp && typeof sample.tireTemp === 'object'
        ? asFiniteNumber(sample.tireTemp[corner])
        : null;
    return next == null && previous.tireTemp ? previous.tireTemp[corner] : next;
}

const tireTemp = {
    fl: readTireTemp('fl'),
    fr: readTireTemp('fr'),
    rl: readTireTemp('rl'),
    rr: readTireTemp('rr')
};

cars[String(carId)] = {
    raceId,
    teamId,
    carId,
    lap,
    trackPos,
    speed,
    avgSpeedKmh,
    rpm: rpm == null ? previous.rpm : rpm,
    gear: gear == null ? previous.gear : gear,
    throttle: throttle == null ? previous.throttle : throttle,
    brake: brake == null ? previous.brake : brake,
    drs,
    tireTemp,
    fuel: fuel == null ? previous.fuel : fuel,
    state: sample.state || previous.state || 'RUNNING',
    timestamp: sample.timestamp || envelope.timestamp || new Date().toISOString(),
    receivedAt: envelope.receivedAt || new Date().toISOString(),
    observedAtMs: nowMs
};
flow.set(carsKey, cars);

const raceIds = flow.get('raceIds') || [];
if (!raceIds.includes(raceId)) {
    raceIds.push(raceId);
    flow.set('raceIds', raceIds);
}

const lastStatusAt = context.get('lastStatusAt') || 0;
if (nowMs - lastStatusAt >= 1000) {
    context.set('lastStatusAt', nowMs);
    node.status({ fill: 'green', shape: 'dot', text: 'cached ' + Object.keys(cars).length + ' cars race ' + raceId });
}
return null;

const LIMITS = {
    tireTempCriticalC: 170,
    fuelWarningKg: 5,
    stationarySpeedKmh: 1,
    stationaryMs: 5000,
    trackProgressJump: 0.2,
    trackProgressBackstep: 0.05
};

const DEDUP_WINDOWS_MS = {
    'tire-overheat': 10000,
    'low-fuel': 30000,
    'stationary-running': 10000,
    'track-position-jump': 10000
};

function asInteger(value) {
    const n = Number(value);
    return Number.isInteger(n) ? n : null;
}

function asFiniteNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function round(value, digits) {
    return Number(value.toFixed(digits));
}

function hottestTire(tireTemp) {
    if (!tireTemp || typeof tireTemp !== 'object') return null;
    return ['fl', 'fr', 'rl', 'rr'].reduce((hottest, corner) => {
        const value = asFiniteNumber(tireTemp[corner]);
        if (value == null) return hottest;
        if (!hottest || value > hottest.value) return { corner, value };
        return hottest;
    }, null);
}

const envelope = msg.payload || {};
const sample = envelope.payload || {};
const raceId = asInteger(sample.raceId != null ? sample.raceId : envelope.raceId);
const carId = asInteger(sample.carId != null ? sample.carId : envelope.carId);
const lap = asInteger(sample.lap);
const trackPos = asFiniteNumber(sample.trackPos);
const teamId = sample.teamId != null ? String(sample.teamId) : null;

if (!raceId || !carId || !teamId || lap == null || trackPos == null) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'telemetry skipped' });
    return [null, null];
}

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const sampleTimestamp = new Date(sample.timestamp || envelope.timestamp || nowIso);
const observedMs = Number.isNaN(sampleTimestamp.getTime()) ? nowMs : sampleTimestamp.getTime();
const raceKey = 'race.' + raceId;
const detectorCarsKey = raceKey + '.eventDetection.cars';
const lastEventsKey = raceKey + '.lastEvents';
const detectorCars = flow.get(detectorCarsKey) || {};
const lastEvents = flow.get(lastEventsKey) || {};
const previous = detectorCars[String(carId)] || {};
const eventEnvelopes = [];
const mqttEvents = [];

const lastCleanupAt = context.get('lastCleanupAt') || 0;
if (nowMs - lastCleanupAt >= 5000) {
    for (const [key, lastSeenMs] of Object.entries(lastEvents)) {
        if (nowMs - lastSeenMs > 120000) delete lastEvents[key];
    }
    context.set('lastCleanupAt', nowMs);
}

function shouldEmit(reason, windowMs) {
    const key = carId + ':' + reason;
    if (lastEvents[key] && nowMs - lastEvents[key] < windowMs) return false;
    lastEvents[key] = nowMs;
    return true;
}

function pushEvent(type, details, reason) {
    if (!shouldEmit(reason, DEDUP_WINDOWS_MS[reason] || 10000)) return;

    const eventDoc = {
        timestamp: sample.timestamp || envelope.timestamp || nowIso,
        raceId,
        teamId,
        carId,
        type,
        details
    };
    const topic = 'f1/simulation/' + raceId + '/teams/' + teamId + '/cars/' + carId + '/events';
    const eventEnvelope = {
        kind: 'event',
        raceId,
        teamId,
        carId,
        topic,
        timestamp: eventDoc.timestamp,
        receivedAt: nowIso,
        payload: eventDoc
    };

    eventEnvelopes.push({
        topic,
        kind: 'event',
        meta: { kind: 'event', raceId, teamId, carId, route: 'car', topic, receivedAt: nowIso, derived: true },
        payload: eventEnvelope,
        doc: eventEnvelope
    });
    mqttEvents.push({ topic, qos: 1, retain: false, payload: eventDoc });
}

const tire = hottestTire(sample.tireTemp);
if (tire && tire.value >= LIMITS.tireTempCriticalC) {
    pushEvent('fault', {
        reason: 'tire-overheat',
        corner: tire.corner,
        tireTemp: round(tire.value, 2),
        threshold: LIMITS.tireTempCriticalC,
        source: 'node-red-event-detection'
    }, 'tire-overheat');
}

const fuel = asFiniteNumber(sample.fuel);
const state = typeof sample.state === 'string' ? sample.state : 'RUNNING';
const flagDoc = flow.get(raceKey + '.flag') || {};
const activeFlag = String(flagDoc.flag || '').toUpperCase();
const flagActive = flagDoc.active !== false;
const raceSuspended = flagActive && activeFlag === 'RED';
if (fuel != null && fuel <= LIMITS.fuelWarningKg && state !== 'PIT' && state !== 'RETIRED' && state !== 'FINISHED') {
    pushEvent('state-change', {
        from: state,
        to: 'PIT',
        reason: 'low-fuel'
    }, 'low-fuel');
}

const speed = asFiniteNumber(sample.speed);
const stationary = !raceSuspended && state === 'RUNNING' && speed != null && speed <= LIMITS.stationarySpeedKmh;
const stationarySinceMs = stationary ? (previous.stationarySinceMs || observedMs) : null;
if (stationary && observedMs - stationarySinceMs >= LIMITS.stationaryMs) {
    pushEvent('retirement', {
        reason: 'stationary-running',
        durationMs: observedMs - stationarySinceMs,
        speed: round(speed, 3),
        threshold: LIMITS.stationarySpeedKmh,
        source: 'node-red-event-detection'
    }, 'stationary-running');
}

const progress = lap + trackPos;
if (Number.isFinite(previous.progress)) {
    const delta = progress - previous.progress;
    if (delta > LIMITS.trackProgressJump || delta < -LIMITS.trackProgressBackstep) {
        pushEvent('fault', {
            reason: 'track-position-jump',
            previousLap: previous.lap,
            previousTrackPos: round(previous.trackPos, 5),
            currentLap: lap,
            currentTrackPos: round(trackPos, 5),
            delta: round(delta, 5),
            source: 'node-red-event-detection'
        }, 'track-position-jump');
    }
}

detectorCars[String(carId)] = {
    lap,
    trackPos,
    progress,
    stationarySinceMs,
    observedMs
};
flow.set(detectorCarsKey, detectorCars);
flow.set(lastEventsKey, lastEvents);

if (eventEnvelopes.length > 0) {
    node.status({ fill: 'orange', shape: 'dot', text: eventEnvelopes.length + ' event(s)' });
} else {
    const lastStatusAt = context.get('lastStatusAt') || 0;
    if (nowMs - lastStatusAt >= 1000) {
        context.set('lastStatusAt', nowMs);
        node.status({ fill: 'green', shape: 'ring', text: 'nominal' });
    }
}
return [eventEnvelopes.length ? eventEnvelopes : null, mqttEvents.length ? mqttEvents : null];

const ALLOWED_FLAGS = {
    GREEN: true,
    YELLOW: true,
    RED: true,
    CHECKERED: true,
    SC: true,
    VSC: true
};

function asInteger(value) {
    const n = Number(value);
    return Number.isInteger(n) ? n : null;
}

function isoTimestamp(value) {
    const parsed = new Date(value || Date.now());
    if (Number.isNaN(parsed.getTime())) return null;
    return parsed.toISOString();
}

function fail(reason, details) {
    const err = {
        error: reason,
        details: details || {},
        topic: msg.topic,
        receivedAt: new Date().toISOString(),
        originalPayload: msg.payload
    };
    msg.error = { message: reason, source: 'race-control-flag-handler' };
    msg.payload = err;
    node.status({ fill: 'red', shape: 'ring', text: reason });
    return [null, null, null, msg];
}

function rememberRaceId(raceId) {
    const raceIds = flow.get('raceIds') || [];
    if (!raceIds.includes(raceId)) {
        raceIds.push(raceId);
        flow.set('raceIds', raceIds);
    }
}

function buildEffects(flagDoc) {
    const base = {
        mode: 'nominal',
        speedMultiplier: 1,
        overtakingAllowed: true,
        raceSuspended: false,
        safetyCar: false,
        virtualSafetyCar: false,
        localSector: null,
        finish: false
    };

    if (!flagDoc.active) {
        return { ...base, mode: 'clear' };
    }

    if (flagDoc.flag === 'YELLOW') {
        return {
            ...base,
            mode: 'caution',
            speedMultiplier: 0.65,
            overtakingAllowed: false,
            localSector: flagDoc.sector
        };
    }
    if (flagDoc.flag === 'RED') {
        return {
            ...base,
            mode: 'suspended',
            speedMultiplier: 0,
            overtakingAllowed: false,
            raceSuspended: true
        };
    }
    if (flagDoc.flag === 'SC') {
        return {
            ...base,
            mode: 'safety-car',
            speedMultiplier: 0.45,
            overtakingAllowed: false,
            safetyCar: true
        };
    }
    if (flagDoc.flag === 'VSC') {
        return {
            ...base,
            mode: 'virtual-safety-car',
            speedMultiplier: 0.55,
            overtakingAllowed: false,
            virtualSafetyCar: true
        };
    }
    if (flagDoc.flag === 'CHECKERED') {
        return {
            ...base,
            mode: 'finish',
            speedMultiplier: 0.8,
            finish: true
        };
    }

    return base;
}

const envelope = msg.payload || {};
const source = envelope.payload || {};
const raceId = asInteger(source.raceId != null ? source.raceId : envelope.raceId);
const flag = typeof source.flag === 'string' ? source.flag.toUpperCase() : '';
const timestamp = isoTimestamp(source.timestamp || envelope.timestamp);
const active = source.active;
let sector = source.sector == null ? null : asInteger(source.sector);

if (!raceId) return fail('invalid raceId', { raceId: source.raceId || envelope.raceId });
if (!ALLOWED_FLAGS[flag]) return fail('invalid flag', { flag: source.flag });
if (typeof active !== 'boolean') return fail('invalid flag active state', { active });
if (!timestamp) return fail('invalid flag timestamp', { timestamp: source.timestamp || envelope.timestamp });
if (flag === 'YELLOW' && sector != null && (sector < 1 || sector > 3)) {
    return fail('invalid yellow sector', { sector: source.sector });
}
if (flag !== 'YELLOW') sector = null;

const flagDoc = {
    ...source,
    timestamp,
    raceId,
    flag,
    active,
    sector,
    reason: source.reason == null ? null : String(source.reason)
};
const effects = buildEffects(flagDoc);
const raceKey = 'race.' + raceId;

flow.set(raceKey + '.flag', flagDoc);
flow.set(raceKey + '.raceEffects', effects);
rememberRaceId(raceId);

const normalizedEnvelope = {
    kind: 'flag',
    raceId,
    teamId: null,
    carId: null,
    topic: envelope.topic || msg.topic,
    timestamp,
    receivedAt: envelope.receivedAt || new Date().toISOString(),
    payload: flagDoc
};

const dashboardMsg = {
    ...msg,
    kind: 'flag',
    dashboardType: 'race-control',
    dashboardEffects: effects,
    payload: normalizedEnvelope,
    doc: normalizedEnvelope
};
const mongoMsg = {
    ...msg,
    kind: 'flag',
    payload: normalizedEnvelope,
    doc: normalizedEnvelope
};
const effectMsg = {
    topic: 'race-control/effects',
    payload: {
        type: 'race-effect',
        timestamp,
        raceId,
        flag: flagDoc,
        effects
    }
};

node.status({ fill: 'green', shape: 'dot', text: flag + ' race ' + raceId });
return [dashboardMsg, mongoMsg, effectMsg, null];

const crypto = global.get('crypto');
const KEY_ENV = 'F1_TELEMETRY_CRYPTO_KEY_B64';

function fail(reason, details) {
    const err = {
        error: reason,
        details: details || {},
        topic: msg.topic,
        receivedAt: new Date().toISOString(),
        originalPayload: msg.payload
    };
    msg.error = { message: reason, source: 'decrypt-secure-flag' };
    msg.payload = err;
    node.status({ fill: 'red', shape: 'ring', text: reason });
    return [null, msg];
}

function keyFromEnv() {
    const value = String(env.get(KEY_ENV) || '').trim();
    if (!value) throw new Error(KEY_ENV + ' missing');
    const key = Buffer.from(value, 'base64');
    if (key.length !== 32) throw new Error(KEY_ENV + ' must decode to 32 bytes');
    return key;
}

function asObject(value) {
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer(value)) value = value.toString('utf8');
    if (typeof value === 'string') return JSON.parse(value);
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    throw new Error('payload is not an object');
}

function b64(value, expectedLength, name) {
    if (typeof value !== 'string' || !value) throw new Error('missing ' + name);
    const buf = Buffer.from(value, 'base64');
    if (expectedLength && buf.length !== expectedLength) throw new Error('invalid ' + name + ' length');
    return buf;
}

function clearTopicFromSecure(topic) {
    const parts = String(topic || '').split('/');
    if (parts.length !== 6 || parts[0] !== 'f1' || parts[1] !== 'simulation' || parts[3] !== 'secure' || parts[4] !== 'race-control' || parts[5] !== 'flags') {
        throw new Error('invalid secure topic');
    }
    const raceId = Number(parts[2]);
    if (!Number.isInteger(raceId)) throw new Error('invalid raceId in secure topic');
    return 'f1/simulation/' + raceId + '/race-control/flags';
}

try {
    if (!crypto) throw new Error('crypto module unavailable');
    const secureTopic = msg.topic;
    const clearTopic = clearTopicFromSecure(secureTopic);
    const envelope = asObject(msg.payload);
    const iv = b64(envelope.iv, 12, 'iv');
    const tag = b64(envelope.tag, 16, 'tag');
    const ciphertext = b64(envelope.ciphertext, 0, 'ciphertext');

    const decipher = crypto.createDecipheriv('aes-256-gcm', keyFromEnv(), iv);
    decipher.setAAD(Buffer.from(secureTopic, 'utf8'));
    decipher.setAuthTag(tag);
    const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');

    msg.topic = clearTopic;
    msg.qos = 1;
    msg.retain = true;
    msg.secure = { decrypted: true, sourceTopic: secureTopic };
    msg.payload = JSON.parse(plaintext);
    node.status({ fill: 'green', shape: 'dot', text: 'decrypted ' + clearTopic });
    return [msg, null];
} catch (err) {
    return fail(err.message || 'decrypt failed');
}

const crypto = global.get('crypto');
const KEY_ENV = 'F1_TELEMETRY_CRYPTO_KEY_B64';

function fail(reason, details) {
    const err = {
        error: reason,
        details: details || {},
        topic: msg.topic,
        receivedAt: new Date().toISOString(),
        originalPayload: msg.payload
    };
