}

function keyFromEnv() {
    const value = String(env.get(KEY_ENV) || '').trim();
    if (!value) throw new Error(KEY_ENV + ' missing');
    const key = Buffer.from(value, 'base64');
    if (key.length !== 32) throw new Error(KEY_ENV + ' must decode to 32 bytes');
    return key;
}

function asObject(value) {
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer(value)) value = value.toString('utf8');
    if (typeof value === 'string') return JSON.parse(value);
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    throw new Error('payload is not an object');
}

function raceIdFromTopic(topic) {
    const parts = String(topic || '').split('/');
    if (parts[0] === 'f1' && parts[1] === 'simulation') {
        const n = Number(parts[2]);
        if (Number.isInteger(n)) return n;
    }
    return null;
}

try {
    if (!crypto) throw new Error('crypto module unavailable');
    const payload = asObject(msg.payload);
    const raceId = Number.isInteger(Number(payload.raceId)) ? Number(payload.raceId) : raceIdFromTopic(msg.topic);
    if (!raceId) throw new Error('invalid raceId for secure topic');

    const secureTopic = 'f1/simulation/' + raceId + '/secure/race-control/flags';
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', keyFromEnv(), iv);
    cipher.setAAD(Buffer.from(secureTopic, 'utf8'));
    const plaintext = Buffer.from(JSON.stringify(payload), 'utf8');
    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const tag = cipher.getAuthTag();

    msg.topic = secureTopic;
    msg.qos = 1;
    msg.retain = false;
    msg.payload = {
        iv: iv.toString('base64'),
        ciphertext: ciphertext.toString('base64'),
        tag: tag.toString('base64')
    };
    node.status({ fill: 'green', shape: 'dot', text: 'encrypted race ' + raceId });
    return [msg, null];
} catch (err) {
    return fail(err.message || 'encrypt failed');
}

