function asInteger(value) {
    const n = Number(value);
    return Number.isInteger(n) ? n : null;
}

function sortCars(a, b) {
    const progressA = (Number(a.lap) || 0) + (Number(a.trackPos) || 0);
    const progressB = (Number(b.lap) || 0) + (Number(b.trackPos) || 0);
    return progressB - progressA || Number(a.carId) - Number(b.carId);
}

const nowIso = new Date().toISOString();
const raceIds = (flow.get('raceIds') || [])
    .map(asInteger)
    .filter((raceId) => raceId != null)
    .sort((a, b) => a - b);
const races = [];

for (const raceId of raceIds) {
    const raceKey = 'race.' + raceId;
    const carsById = flow.get(raceKey + '.cars') || {};
    const statesById = flow.get(raceKey + '.states') || {};
    const cars = Object.values(carsById).map((car) => {
        const state = statesById[String(car.carId)] || {};
        return {
            raceId: car.raceId,
            teamId: car.teamId,
            carId: car.carId,
            lap: car.lap,
            trackPos: car.trackPos,
            speed: car.speed,
            avgSpeedKmh: car.avgSpeedKmh,
            rpm: car.rpm,
            gear: car.gear,
            throttle: car.throttle,
            brake: car.brake,
            drs: car.drs,
            tireTemp: car.tireTemp,
            fuel: car.fuel,
            state: state.state || car.state,
            previousState: state.previousState,
            reason: state.reason,
            timestamp: car.timestamp,
            receivedAt: car.receivedAt
        };
    }).sort(sortCars);

    const flag = flow.get(raceKey + '.flag') || null;
    const effects = flow.get(raceKey + '.raceEffects') || null;
    const classification = flow.get(raceKey + '.lastClassification') || null;

    if (cars.length === 0 && !flag && !classification) continue;

    races.push({
        raceId,
        flag,
        effects,
        classification,
        cars
    });
}

if (races.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'waiting data' });
    return null;
}

msg.topic = 'dashboard/snapshot';
msg.payload = JSON.stringify({
    type: 'snapshot',
    timestamp: nowIso,
    races
});
node.status({ fill: 'blue', shape: 'dot', text: 'snapshot ' + races.length + ' race(s)' });
return msg;

